// client/src/api/couponApi.js 파일

// ❌ 에러 발생 구문:
// import axiosIntance from './axiosIntance'; 

// ✅ 정확한 수정 구문:
import axiosInstance from './axiosInstance'; 
//       ^ i와 s가 추가됨

// 이제 axiosInstance를 사용하여 API 함수를 작성합니다.
const COUPON_URL = '/coupons';

// 1. 사용자 쿠폰 목록 가져오기
export const getMyCoupons = async () => {
    try {
        const response = await axiosInstance.get(COUPON_URL);
        return response.data;
    } catch (error) {
        throw error.response?.data?.message || '쿠폰 목록 조회 실패';
    }
};

